from collections import deque

def fewest_stops(graph, start, target):
    seen = {start}
    queue = deque([(start, 0)])
    while queue:
        node, stops = queue.popleft()
        if node == target:
            return stops
        for nxt in graph[node]:
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, stops + 1))
    return -1

